raw=dict(date=D,status='integrated_second_challenge_draft_for_review',first_pass_preserved=True,selected_model_ids=[f'T01-M{i:02}' for i in range(1,7)],model_changes=[dict(model_id=i,refinement=t,transfer_limit=l,claim_ids=c) for i,t,l,c in model_updates],conditions=conditions,original_T02_hypothesis_ids=['T02-H01','T02-H02','T02-H03','T02-H04'],hypotheses_replaced=False,additional_mandatory_questions=0,ranking=False,commercial_validation=False,participant_observations=[],actual_Table_conversations=[],financial_inputs=[],new_price_recommendations=[],prior_model_reruns=False,prior_recommendation_counts_reused=False)
